{
  "technical_and_design_decisions": [
    "Fix U1 by initializing a default Sqoop connection manager when an explicit JDBC driver is supplied, preventing the NPE, rather than forcing use of the Hortonworks Teradata connector.",
    "Make the log directory configurable via a new property `xd.log.dir` (default `${xd.home}/logs`), consumed by the logging framework at startup; RPM packaging sets it to `/var/log/spring-xd`.",
    "Extract message-bus and serialization codec into a separate `spring-bus` Maven artifact, exposing the same public APIs so Spring XD can depend on it.",
    "Move input/output type conversion into `spring-cloud-dataflow` to enable reuse by custom modules, defining a clear conversion SPI.",
    "Implement the single-node Admin SPI (`SingleNodeAdmin`) using the existing `ModuleLauncher` to deploy modules inside one JVM with a shared parent context.",
    "Implement the Diego Admin SPI (`DiegoAdmin`) via a REST client to the Diego Receptor API, reusing `ModuleLauncher` for module packaging and lifecycle.",
    "For U8, base the investigation on Spring Cloud `DiscoveryClient` (e.g., Eureka/Consul) to allow modules to self-register and XD to discover them.",
    "Maintain backward compatibility: default behaviors, stream/job definitions, and existing configurations remain unchanged after refactors.",
    "Use Maven for builds, semantic versioning, and publish snapshot artifacts to an internal repository for integration."
  ],
  "assumptions": [
    "A single developer with working knowledge of Spring XD, Sqoop, and Spring Cloud performs all tasks.",
    "A Teradata test instance (or Teradata Express VM) and the official Teradata JDBC driver are available for testing U1.",
    "The `spring-bus` and `spring-cloud-dataflow` repositories exist or can be created with appropriate write access.",
    "Baseline Spring XD version already contains the `ModuleLauncher` and Admin SPI abstractions required by U6/U7.",
    "For U7, a local Lattice/Diego environment or a mock Receptor HTTP server is available for testing; otherwise tests use mocks.",
    "U8 is treated as a research spike: deliver a prototype and recommendation, not a production-ready feature.",
    "Effort estimates cover analysis, coding, unit/integration testing, and documentation, but exclude end-user training, production deployment, and ongoing maintenance.",
    "All estimates are expressed in work-hours for one developer; no parallelization or calendar constraints are considered.",
    "If minor legacy obstacles are encountered, they are absorbed within the most-likely estimates."
  ],
  "activities": [
    {
      "activity_id": "A01",
      "activity_name": "Requirements analysis and technical design",
      "activity_description": "Analyze the 8 user stories, define overall architecture and technical approach, produce WBS and design documents.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A02",
      "activity_name": "Environment and build setup",
      "activity_description": "Create feature branches, set up new Maven repositories (spring-bus), configure CI pipelines and local dev environment for all affected modules.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A03",
      "activity_name": "U1: Fix Sqoop Teradata JDBC import NPE",
      "activity_description": "Reproduce the null-pointer exception when using Teradata JDBC driver directly, root-cause the Sqoop job module, implement fix, add integration test with Teradata driver, update user docs.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A04",
      "activity_name": "U2: Configurable logging directory",
      "activity_description": "Introduce xd.log.dir property with default to ${xd.home}/logs, refactor logging initialization, update startup scripts and RPM spec to use /var/log/spring-xd, test and document.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A05",
      "activity_name": "U3: Extract message-bus to spring-bus",
      "activity_description": "Create/configure spring-bus repo, move message-bus code, refactor packages, publish artifact, update Spring XD to consume it via Maven, run tests.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A06",
      "activity_name": "U4: Move type conversion to spring-cloud-dataflow",
      "activity_description": "Extract input/output type conversion classes, adjust dependencies, update Spring XD and spring-cloud-dataflow, verify custom module scenario, document.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A07",
      "activity_name": "U5: Move serialization codec to spring-bus",
      "activity_description": "Extract serialization codec from Spring XD into spring-bus, wire dependency, ensure compatibility, test and document.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A08",
      "activity_name": "U6: Single-node XD Admin SPI implementation",
      "activity_description": "Design and implement single-JVM Admin SPI using ModuleLauncher, integrate with XD runtime, add unit/integration tests and local sample.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A09",
      "activity_name": "U7: Diego Receptor XD Admin SPI implementation",
      "activity_description": "Research Diego/Lattice Receptor API, implement REST client and Admin SPI implementation based on ModuleLauncher, test on local Diego/Lattice or mock, document.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A10",
      "activity_name": "U8: Service discovery self-registration spike",
      "activity_description": "Investigate s-c-s module self-registration to service discovery, build prototype using Spring Cloud Discovery, document feasibility and recommendations.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A11",
      "activity_name": "Cross-module integration testing and CI",
      "activity_description": "Run full regression and integration tests across extracted modules and new Admin SPIs, update CI pipelines, fix integration issues.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation and migration guides",
      "activity_description": "Update user guides, migration notes for extracted artifacts, logging config, Teradata usage, and Admin SPI deployment options.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "Release engineering and versioning",
      "activity_description": "Bump versions, publish Maven artifacts, tag source repositories, final code cleanup.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 270
  }
}

